#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# This walkthrough's own helpers.
SITE="http://localhost:3000/fr"
PASSED=()
EMAIL=""

# check "what": asks whether it worked; what didn't is listed at the end.
check() {
  if confirm "$1: did it work?"; then
    PASSED+=("$1")
  else
    SKIPPED+=("didn't work: $1")
  fi
}

# rows "SQL": prints the rows of one read-only query on the database in .env.
rows() {
  QUERY="$1" node -e '
    const { PrismaClient } = require("@prisma/client");
    const db = new PrismaClient();
    db.$queryRawUnsafe(process.env.QUERY)
      .then((r) => { if (r.length === 0) console.log("  (no rows)"); else console.table(r); })
      .catch((e) => console.error("  " + e.message))
      .finally(() => db.$disconnect());'
}

# sql "statement": runs one statement on the database in .env.
sql() {
  printf '%s' "$1" | npx prisma db execute --stdin --schema prisma/schema.prisma
}

# your_holds: the bookings of the test e-mail, newest first.
your_holds() {
  rows "SELECT c.status, to_char(c.\"startsAt\" + interval '1 hour', 'Dy DD Mon HH24:MI') AS \"slot (Douala)\",
               to_char(c.\"heldUntil\" + interval '1 hour', 'HH24:MI:SS') AS \"held until (Douala)\",
               c.country, c.phone, c.topics, c.\"crsScore\", c.\"itaReceived\"
        FROM consultation c JOIN account a ON a.id = c.\"accountId\"
        WHERE a.email = '$EMAIL' ORDER BY c.\"createdAt\" DESC LIMIT 5"
}

run_wizard() {

TOTAL_STAGES=16

banner "Walkthrough: the Consultation page (v2) and booking with a 15-minute hold (#15)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before we start"
say "You'll test, in the browser on your dev server:"
note "  • the public Consultation page, v2 design and motion (PR #180)"
note "  • booking steps 1 and 2: the 15-minute hold, a Compte made at step 1, « Créneau libéré »"
note "  • payment is NOT in this slice: step 3 only says the slot stays held"
say ""
warn "Your $ENV_FILE uses the Neon « test » database (a copy of production, real people in it)"
warn "and sends real e-mails (Resend). Book only with an e-mail address you can read."
say ""
ask EMAIL "Which e-mail will you book with (a new address, with no Compte yet, e.g. you+consult1@gmail.com)?"
EMAIL=$(printf '%s' "$EMAIL" | tr '[:upper:]' '[:lower:]')
while [[ ! "$EMAIL" =~ ^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$ ]]; do
  warn "That doesn't look like an e-mail address."
  ask EMAIL "E-mail to book with?"
  EMAIL=$(printf '%s' "$EMAIL" | tr '[:upper:]' '[:lower:]')
done
say ""
say "At each check, answer y or n: what didn't work is listed at the end."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The database and the dev server"
say "This slice adds one migration (the « consultation » table). It is already on « test »;"
say "running it again only checks."
if confirm "Run « npx prisma migrate deploy » and « prisma generate » now?"; then
  npx prisma migrate deploy && npx prisma generate >/dev/null && printf '  %s✓ database up to date%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("check the migrations: npx prisma migrate deploy && npx prisma generate")
fi
step "Make sure « npm run dev » runs on the branch feat/consultation-booking, restarted after the"
step "  generate, so it knows the new table."
note "If a page says « Unknown argument … » or « consultation does not exist »: stop it, rm -rf .next, npm run dev."
pause "Press Enter once the dev server is running"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The Consultation page, desktop"
open_url "$SITE/services/consultation"
step "Wide window. Hero: Stanzy waves twice in the call, the caption types word by word, three"
step "  lines, then stops on the last. The « REC » dot blinks; the two chips float gently."
step "Scroll slowly through « Comment se passe la consultation »: the dashed route draws, the plane"
step "  follows it, and steps 2 and 3 appear when the plane reaches them."
step "« Ce qu'on aborde »: topics move on every 6 s; Stanzy points at the list, his bubble below."
step "« Un aperçu de votre récap »: tap « 02:40 », the bar jumps; tick a step, it is struck through."
step "Further down: the deliverables' illustrations, the red « On en parle de vive voix ? » band"
step "  (next free slot, Stanzy waves once), the FAQ with Stanzy's avatar."
check "The Consultation page looks and moves as designed (desktop)"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The Consultation page, mobile"
step "DevTools (Cmd+Opt+I) → device toolbar (Cmd+Shift+M) → iPhone 12 Pro, then reload."
step "The route of « Comment se passe » runs down, the plane with it."
step "Scroll past « Choisissez votre créneau »: a bar slides up from the bottom with the slot and"
step "  « Réserver ». Scroll back up to the panel: it slides away. « Changer » scrolls you back to it."
check "The mobile page and its booking bar"
note "Optional: macOS Réglages → Accessibilité → Affichage → « Réduire les animations », reload:"
note "  nothing travels any more (Stanzy still, route drawn, plane at the end). Switch it back after."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Step 1, signed out: a wrong number"
step "Open a PRIVATE window (signed out), $SITE/services/consultation, desktop size."
step "Pick a day and a time in « Choisissez votre créneau », click « Réserver … »."
step "You're on « Finalisez votre réservation »: step 1 open, steps 2 and 3 closed, the summary on"
step "  the right (date, 45 min, price). No timer yet: nothing is held before « Continuer »."
step "Fill Prénom, Nom, your e-mail ($EMAIL), country Cameroun, WhatsApp number « 12 »."
step "« Continuer »: under the number, « Ce numéro ne semble pas valide pour ce pays. »"
check "Step 1 opens with the chosen slot and refuses a wrong number"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Step 1: hold the slot"
step "Number: 6 77 12 34 56 (Cameroun). « Continuer »."
step "A toast « Créneau gardé 15 minutes »; the yellow timer counts down from 15:00;"
step "  step 1 shows done with your details; step 2 « Préparer l'échange » opens."
say "In the database, a HELD booking for your e-mail, the number as +237…:"
your_holds
check "The slot is held 15 minutes, the details saved"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "A held slot is hidden from others"
open_url "$SITE/services/consultation"
step "In your normal window, open the Consultation page on the same day."
step "The time you hold is no longer offered."
check "The held slot left the public page"
step "Your inbox ($EMAIL): « Vérification e-mail » arrived (the Compte was made at step 1)."
warn "Don't click its link yet: stage 13 does."
check "The Vérification e-mail arrived"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Step 2, Préparer l'échange"
step "Back in the private window. Tick « Mon admissibilité » and « Gagner des points CRS » (a"
step "  check fades in), CRS score 452, « Non, pas encore », a few lines: the counter shows N / 500."
step "« Continuer vers le paiement »: toast « Réponses enregistrées »; step 2 done with its summary"
step "  (« Score CRS 452 · pas encore sélectionné · … »); step 3 says the slot stays held until HH:MM."
your_holds
check "The answers are saved and step 3 opens"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "« Modifier »"
step "Step 1 « Modifier »: the name and e-mail are greyed (the Compte's); change the country to"
step "  Côte d'Ivoire (+225), number 07 07 07 07 07, untick the reminders, « Continuer »."
step "Step 2 « Modifier »: your answers are still there; « Continuer vers le paiement »."
your_holds
check "Details and answers can be changed while held"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "« Changer » the slot"
step "In the summary, « Changer » → the Consultation page → pick ANOTHER time → « Réserver »."
step "Step 1 opens prefilled; « Continuer » holds the new slot (no « Compte existe » message)."
step "The summary shows the new time; the timer starts again from 15:00."
your_holds
note "The newest row is HELD on the new slot with your answers; the old one's « held until » is now."
check "The hold moved to the new slot, answers kept, the old slot free again"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "The timer runs out: « Créneau libéré »"
say "Rather than wait 15 minutes, this can make your current hold end in 2½ minutes."
if confirm "Shorten your hold (only your e-mail's held booking)?"; then
  sql "UPDATE consultation SET \"heldUntil\" = now() + interval '150 seconds'
       WHERE status = 'HELD' AND \"heldUntil\" > now()
         AND \"accountId\" = (SELECT id FROM account WHERE email = '$EMAIL');"
  step "Reload the booking page: the timer shows about 02:30 and turns rouge under 2:00."
  step "At 00:00: « Votre créneau a été libéré », the next free slots, « Garder … et payer »."
else
  step "Wait until the timer reaches 00:00 (it turns rouge under 2:00)."
fi
check "Under 2 minutes the timer turns rouge; at 00:00 the slot is released"
step "Pick a slot, « Garder … et payer »: held again, timer back to 15:00, answers still there."
check "A released booking can be held again"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Same e-mail, another browser: sign in"
step "Another private window (or another browser): Consultation page, pick a slot, « Réserver »."
step "Fill step 1 with the SAME e-mail ($EMAIL) and a valid number, « Continuer »."
step "A pink message: « Un Compte existe déjà avec cet e-mail. Connectez-vous… » and « Se connecter »."
step "« Se connecter » opens the sign-in; its address carries next=/services/consultation/reserver?creneau=…"
check "An e-mail with a Compte is asked to sign in, and nothing is held for it"
note "Close that window."
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "The Vérification link signs in and finds the booking"
step "In the FIRST private window (the one holding the slot), open the « Vérification e-mail »"
step "  link from stage 7 (paste it there if your mail app opens another browser)."
step "« Adresse confirmée », signed in. Go to $SITE/services/consultation/reserver"
step "  (no slot in the address): your held booking is back, with the timer."
check "The link confirms the e-mail, signs in, and the held booking is found"

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Signed in: book again"
step "Still signed in: Consultation page, another time, « Réserver »."
step "Step 1: no « Se connecter », the name and e-mail greyed (your Compte's). « Continuer »."
your_holds
note "One HELD row whose « held until » is ahead; the earlier ones are in the past (given back)."
check "Signed in, a Compte holds one slot at a time"

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Two people, one slot"
step "Window A (your normal window, signed in as anyone else or signed out) and window B (private,"
step "  signed out): open the SAME slot's « Réserver » page in both, before continuing in either."
step "A: fill step 1 with another e-mail you read, « Continuer »: held."
step "B: fill step 1 with a third e-mail, « Continuer »: « Ce créneau vient d'être pris »,"
step "  with « Choisir un autre créneau »."
check "A slot held by one person is refused to the other"

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Done"
printf '  %s✓ %s check(s) passed%s\n' "$GREEN" "${#PASSED[@]}" "$RESET"
for item in "${PASSED[@]}"; do note "    ✓ $item"; done
say ""
say "The test bookings stay in « test » as HELD rows: once their 15 minutes pass they free"
say "their slots by themselves, so nothing needs cleaning for the next run. The test Comptes stay too."
say ""
say "Send me what didn't work (listed below) and I'll look into it."
pause

finish
}

run_wizard "$@"; exit
